 for kind,data in [('roots',[ROOT]),('words',W)]: (OUT/(kind+'_batch200_vid_95.json')).write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print('poly:',len(W),'words;',sum(len(e['examples']) for e in W),'examples;',len(ROOT['words']),'references')
